class Projector:
    """Consumes events.jsonl and projects to OpenSwitchboard and TaskLight."""

    def __init__(
        self,
        events_file: str | Path = DEFAULT_EVENTS_LOG,
        state_file: Optional[str | Path] = None,
        sink: Optional[BaseSink] = None,
        osb_room: str = DEFAULT_OSB_ROOM,
        cw_room: str = DEFAULT_CW_ROOM,
        cw_home: Optional[str | Path] = None,
        repo_path: str = DEFAULT_REPO_PATH,
    ) -> None:
        self.events_file = Path(events_file)
        self.state_file = Path(state_file) if state_file else None
        self.osb_room = osb_room
        self.cw_room = cw_room
        self.cw_home = Path(cw_home) if cw_home else None
        self.last_finalize_errors: List[str] = []

        if sink is not None:
            self.sink = sink
            if isinstance(sink, DryRunSink) and self.cw_home and not sink.cw_home:
                sink.cw_home = self.cw_home
        else:
            self.sink = CompositeSink([
                OsbSink(),
                TaskLightMcpSink(cw_home=str(self.cw_home) if self.cw_home else None, repo_path=repo_path),
            ])

        # Load cursor state
        if self.state_file and self.state_file.is_file():
            self.state = ProjectionState.load(self.state_file)
        else:
            self.state = ProjectionState()

        # Auto-open room if needed
        self.sink.ensure_room_opened(self.osb_room)

    def process_record(self, record: Dict[str, Any]) -> bool:
        """Process a single JSON record from events.jsonl according to §7.1 and §7.2."""
        if not isinstance(record, dict):
            return False

        rec = record.get("rec")

        # §7.1: Skip cursor records
        if rec == "cursor":
            return False

        # §7.1: Skip claim (lease grant/renewal)
        if rec == "claim":
            return False

        # 1. Enqueue
        if rec == "enqueue":
            agent_id = record.get("agent_id", "")
            event_id = record.get("event_id", "")
            lane = record.get("lane", "")
            kind = record.get("kind", "")
            based_on_frame = record.get("based_on_frame", 0)

            # OSB projection
            osb_text = f"enqueue {event_id} ({lane}/{kind}) frame={based_on_frame}"
            self.sink.post_osb(
                room=self.osb_room,
                agent=agent_id,
                act="claim",
                text=osb_text,
                ref=event_id,
            )

            # TaskLight projection: on agent's FIRST enqueue, post_plan
            if agent_id in TRACKED_AGENTS and agent_id not in self.state.planned_agents:
                title = f"Task plan for {agent_id}"[:120]
                steps = get_default_plan_steps(agent_id)
                self.sink.post_plan(
                    room=self.cw_room,
                    agent=agent_id,
                    title=title,
                    steps=steps,
                )
                self.state.planned_agents.add(agent_id)

            intents = self.state.open_intents.setdefault(agent_id, [])
            if event_id and event_id not in intents:
                intents.append(event_id)
            return True

        # 2. Turn
        if rec == "turn":
            # n2: Skip zero-hold PASS turns (no ack, handoff, or post_status)
            if record.get("hold_ms") == 0:
                return False

            current_agent = record.get("agent_id", "")
            turn = record.get("turn", 0)
            turn_epoch = record.get("turn_epoch", turn)
            head_frame = record.get("head_frame", 0)

            # Token transfer check between consecutive turn records
            prev_agent = self.state.prev_turn_agent
            if prev_agent and prev_agent != current_agent:
                handoff_text = f"handoff -> {current_agent} (turn_epoch={turn_epoch})"
                self.sink.post_osb(
                    room=self.osb_room,
                    agent=prev_agent,
                    act="handoff",
                    text=handoff_text,
                    ref=f"turn-{turn_epoch}",
                )

            self.state.prev_turn_agent = current_agent

            # Turn granted ack
            turn_text = f"turn={turn} turn_epoch={turn_epoch} head={current_agent} frame={head_frame}"
            self.sink.post_osb(
                room=self.osb_room,
                agent="broker-projector",
                act="ack",
                text=turn_text,
                ref=f"turn-{turn_epoch}",
            )

            # TaskLight status
            if current_agent in TRACKED_AGENTS:
                self.sink.post_status(
                    room=self.cw_room,
                    agent=current_agent,
                    text=f"Acting on turn #{turn}",
                )
            return True

        # 3. Close
        if rec == "close":
            verdict = record.get("verdict", "")
            event_id = record.get("event_id")
            agent_id = record.get("agent_id", "")
            turn = record.get("turn", 0)

            # m4: Skip close early ONLY when verdict == "PASS" or event_id == "PASS"
            if verdict == "PASS" or event_id == "PASS":
                return False

            if verdict in ADMITTED_VERDICTS:
                tick = record.get("tick", 0)
                verify_frame = record.get("verify_frame_ref")
                ev_ref = str(event_id) if event_id else f"admitted-turn-{turn}-{agent_id}"
                evidence_text = f"close {event_id or ev_ref} verdict={verdict} tick={tick} verify_frame={verify_frame}"
                self.sink.post_osb(
                    room=self.osb_room,
                    agent=agent_id,
                    act="evidence",
                    text=evidence_text,
                    ref=ev_ref,
                )

                if agent_id in TRACKED_AGENTS:
                    # m1: 12-step rollover
                    step_idx = self.state.get_step_index(agent_id)
                    if step_idx >= 12:
                        gen = self.state.advance_plan_generation(agent_id)
                        title = f"Task plan for {agent_id} (cont. #{gen})"[:120]
                        steps = get_default_plan_steps(agent_id)
                        self.sink.post_plan(
                            room=self.cw_room,
                            agent=agent_id,
                            title=title,
                            steps=steps,
                        )
                        step_idx = 0

                    outcome = f"{event_id or ev_ref}: {verdict}"[:240]
                    self.sink.post_step(
                        room=self.cw_room,
                        agent=agent_id,
                        index=step_idx,
                        state="done",
                        outcome=outcome,
                    )
                    self.state.increment_step_index(agent_id)

                # Remove from open intents
                intents = self.state.open_intents.get(agent_id, [])
                if event_id and event_id in intents:
                    intents.remove(event_id)
                return True

            if verdict in REFUSAL_VERDICTS or verdict:
                # Refusal or error
                drops = record.get("drops", 0)
                reason = record.get("reason", "")
                if verdict not in REFUSAL_VERDICTS:
                    logger.warning("Unrecognized verdict %r mapped to refute/blocked for event %s", verdict, event_id)

                # m4 & m2: Synthesize deterministic non-empty ref if event_id is null/empty
                if event_id and str(event_id).strip():
                    ref_str = str(event_id).strip()
                else:
                    ref_str = f"refusal-turn-{turn}-{agent_id}"

                refute_text = f"refute {ref_str} verdict={verdict} drops={drops} reason={reason}"
                self.sink.post_osb(
                    room=self.osb_room,
                    agent="broker-projector",
                    act="refute",
                    text=refute_text,
                    ref=ref_str,
                )

                self.state.refusals.append({
                    "event_id": event_id or ref_str,
                    "agent_id": agent_id,
                    "verdict": verdict,
                    "ref": ref_str,
                })

                if agent_id in TRACKED_AGENTS:
                    # m1: 12-step rollover
                    step_idx = self.state.get_step_index(agent_id)
                    if step_idx >= 12:
                        gen = self.state.advance_plan_generation(agent_id)
                        title = f"Task plan for {agent_id} (cont. #{gen})"[:120]
                        steps = get_default_plan_steps(agent_id)
                        self.sink.post_plan(
                            room=self.cw_room,
                            agent=agent_id,
                            title=title,
                            steps=steps,
                        )
                        step_idx = 0

                    outcome = f"{event_id or ref_str}: {verdict}"[:240]
                    self.sink.post_step(
                        room=self.cw_room,
                        agent=agent_id,
                        index=step_idx,
                        state="blocked",
                        outcome=outcome,
                    )
                    self.state.increment_step_index(agent_id)

                if verdict in ("INPUT_UNCERTAIN", "OUTCOME_UNCERTAIN"):
                    target_uncertain = event_id or ref_str
                    if target_uncertain and target_uncertain not in self.state.uncertain_events:
                        self.state.uncertain_events.append(target_uncertain)
                return True

        # 4. Control
        if rec == "control":
            op = record.get("op", "")
            reason = record.get("reason", "")
            by = record.get("by", "director-agent")

            if op in ("stop", "resume"):
                ctrl_text = f"control op={op} reason={reason}"
                self.sink.post_osb(
                    room=self.osb_room,
                    agent=by or "director-agent",
                    act="verdict",
                    text=ctrl_text,
                    ref=f"control-{op}",
                )

            # M2: On stop, pause status instead of prematurely closing tasks
            if op == "stop":
                for agent_id in sorted(self.state.planned_agents):
                    if agent_id in TRACKED_AGENTS and agent_id not in self.state.closed_agents:
                        self.sink.post_status(
                            room=self.cw_room,
                            agent=agent_id,
                            text="Paused: broker control stop",
                        )

            # M2: On resume, post resumed status for active planned agents
            if op == "resume":
                for agent_id in sorted(self.state.planned_agents):
                    if agent_id in TRACKED_AGENTS and agent_id not in self.state.closed_agents:
                        self.sink.post_status(
                            room=self.cw_room,
                            agent=agent_id,
                            text="Resumed: broker control resume",
                        )

            if op == "park":
                # m2: extract park target from top-level fields or parse from reason
                target = extract_park_target(record)
                ref_str = str(target)
                drops = record.get("drops", 0)
                verdict = record.get("verdict", "PARK")
                refute_text = f"refute {ref_str} verdict={verdict} drops={drops} reason={reason}"
                self.sink.post_osb(
                    room=self.osb_room,
                    agent="broker-projector",
                    act="refute",
                    text=refute_text,
                    ref=ref_str,
                )

            if op == "reconcile":
                # Clear pending uncertain events (explicit reconcile only)
                self.state.uncertain_events.clear()

            return True

        return False

    def finalize_open_tasks(self, reason: str = "") -> None:
        """Close open tasks for all agents that have planned but not yet closed.
        M1: ONLY add agent_id to state.closed_agents if sink.close_task succeeded without error."""
        self.last_finalize_errors.clear()
        for agent_id in sorted(self.state.planned_agents):
            if agent_id in TRACKED_AGENTS and agent_id not in self.state.closed_agents:
                outcome = f"Completed capsule tasks for {agent_id}"
                if reason:
                    outcome += f" ({reason})"
                res = self.sink.close_task(
                    room=self.cw_room,
                    agent=agent_id,
                    outcome=outcome[:240],
                )
                if isinstance(res, dict) and res.get("isError"):
                    err_msg = f"close_task failed for {agent_id}: {res}"
                    logger.error(err_msg)
                    self.last_finalize_errors.append(err_msg)
                else:
                    self.state.closed_agents.add(agent_id)

    def run_once(self) -> int:
        """Process available lines in events_file up to EOF.
        m5: Only process lines ending with \n, hold offset on partial line.
        m8: Only save state when offset_bytes or state actually changed."""
        if not self.events_file.is_file():
            logger.info("Events file %s does not exist yet.", self.events_file)
            return 0

        initial_offset = self.state.offset_bytes
        lines_processed = 0

        with open(self.events_file, "r", encoding="utf-8") as f:
            if self.state.offset_bytes > 0:
                f.seek(self.state.offset_bytes)

            while True:
                line_start_offset = f.tell()
                line = f.readline()
                if not line:
                    break
                # m5: Hold offset on partial line without trailing newline
                if not line.endswith("\n"):
                    f.seek(line_start_offset)
                    break

                stripped = line.strip()
                if stripped:
                    try:
                        record = json.loads(stripped)
                        self.process_record(record)
                    except json.JSONDecodeError as e:
                        logger.warning("Skipping invalid JSON at line %d: %s", self.state.line_number + 1, e)

                self.state.offset_bytes = f.tell()
                self.state.line_number += 1
                lines_processed += 1

        # m8: Only save state if offset_bytes actually advanced
        if self.state_file and self.state.offset_bytes != initial_offset:
            self.state.save(self.state_file)

        return lines_processed

    def run_follow(self, poll_interval_s: float = 0.1, max_idle_s: Optional[float] = None) -> None:
        """Poll events_file for new lines until interrupted."""
        idle_time = 0.0
        try:
            while True:
                processed = self.run_once()
                if processed > 0:
                    idle_time = 0.0
                else:
                    time.sleep(poll_interval_s)
                    idle_time += poll_interval_s
                    if max_idle_s and idle_time >= max_idle_s:
                        break
        except KeyboardInterrupt:
            logger.info("Projection follow interrupted by user.")
        finally:
            if self.state_file:
                self.state.save(self.state_file)

    def finalize(self) -> Any:
        """Finalize open tasks and execute reconciliation audit."""
        self.finalize_open_tasks()
        if self.state_file:
            self.state.save(self.state_file)

        from .reconciler import Reconciler
        reconciler = Reconciler(
            events_file=self.events_file,
            cw_home=self.cw_home,
            cw_room=self.cw_room,
            state=self.state,
        )
        report = reconciler.audit()
        return report

    def close(self) -> None:
        self.sink.close()


# ----------------------------------------------------------------------
# CLI Interface
# ----------------------------------------------------------------------

def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="OpenSwitchboard & TaskLight Event Projector (swarm.projection)",
    )
    parser.add_argument(
        "--events-file",
        default=os.environ.get("SWARM_EVENTS_LOG", DEFAULT_EVENTS_LOG),
        help="Path to authoritative events.jsonl",
    )
    parser.add_argument(
        "--state-file",
        default=None,
        help="Path to cursor state JSON file for offset tracking",
    )
    parser.add_argument(
        "--cw-home",
        default=None,
        help="Context-wall home directory (defaults to CW_HOME or ~/.context-wall)",
    )
    parser.add_argument(
        "--osb-room",
        default=DEFAULT_OSB_ROOM,
        help="Target OpenSwitchboard room slug",
    )
    parser.add_argument(
        "--cw-room",
        default=DEFAULT_CW_ROOM,
        help="Target TaskLight context-wall room slug",
    )
    parser.add_argument(
        "--sink",
        choices=["all", "osb", "mcp", "dry-run"],
        default="all",
        help="Sink backend to use",
    )
    parser.add_argument(
        "--once",
        action="store_true",
        help="Process events to EOF and exit",
    )
    parser.add_argument(
        "--follow",
        action="store_true",
        help="Keep polling events.jsonl in daemon mode",
    )
    parser.add_argument(
        "--finalize",
        action="store_true",
        help="Close open tasks and run reconciler audit on completion",
    )
    return parser.parse_args(argv)


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = parse_args(argv)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(name)s: %(message)s")

    # Instantiate chosen sink
    if args.sink == "dry-run":
        sink: BaseSink = DryRunSink(cw_home=args.cw_home)
    elif args.sink == "osb":
        sink = OsbSink()
    elif args.sink == "mcp":
        sink = TaskLightMcpSink(cw_home=args.cw_home)
    else:
        sink = CompositeSink([
            OsbSink(),
            TaskLightMcpSink(cw_home=args.cw_home),
        ])

    projector = Projector(
        events_file=args.events_file,
        state_file=args.state_file,
        sink=sink,
        osb_room=args.osb_room,
        cw_room=args.cw_room,
        cw_home=args.cw_home,
    )

    try:
        if args.follow:
            projector.run_follow()
        else:
            projector.run_once()

        if args.finalize:
            report = projector.finalize()
            print(json.dumps(report.to_dict(), indent=2))
            return 0 if report.clean else 1

        return 0
    finally:
        projector.close()


if __name__ == "__main__":
    sys.exit(main())

"""OpenSwitchboard & TaskLight Event Reconciler (`swarm.projection.reconciler`).

Audits projected state and TaskLight room state against authoritative `events.jsonl`.
Enforces the Negative-Control rule:
- Flags any agent that emitted `post_plan` (or `enqueue`) without a matching `close_task` (`MISSING_CLOSE_TASK`).
- Flags any discrepancy where state claims closed but room store lacks `act == "close"` (`STATE_ROOM_MISMATCH`).
- Flags any refusal lacking `--ref` (`MISSING_REF_ON_REFUSAL`).
- Flags any `INPUT_UNCERTAIN` or `OUTCOME_UNCERTAIN` event without reconciliation (`UNRECONCILED_UNCERTAIN_EVENT`).

Exits with `rc = 0` when clean, `rc = 1` when anomalies exist.
"""

from __future__ import annotations

import argparse
import json
import logging
import os
from pathlib import Path
import sys
from typing import Any, Dict, List, Optional, Sequence, Set

from .projector import (
    ADMITTED_VERDICTS,
    DEFAULT_CW_ROOM,
    DEFAULT_EVENTS_LOG,
    REFUSAL_VERDICTS,
    TRACKED_AGENTS,
    ProjectionState,
    extract_park_target,
)

logger = logging.getLogger("swarm.projection.reconciler")


class ReconciliationReport:
    """Structured report emitted by the projection reconciler."""

    def __init__(
        self,
        clean: bool,
        status: str,
        anomalies: List[Dict[str, Any]],
        stats: Dict[str, Any],
    ) -> None:
        self.clean = bool(clean)
        self.status = str(status)
        self.anomalies = list(anomalies)
        self.stats = dict(stats)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "clean": self.clean,
            "status": self.status,
            "anomalies": self.anomalies,
            "stats": self.stats,
        }

    def to_json(self, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent)


class Reconciler:
    """Audits broker events against TaskLight and OSB projection constraints."""

    def __init__(
        self,
        events_file: str | Path = DEFAULT_EVENTS_LOG,
        cw_home: Optional[str | Path] = None,
        cw_room: str = DEFAULT_CW_ROOM,
        cw_events_file: Optional[str | Path] = None,
        state: Optional[ProjectionState] = None,
        state_file: Optional[str | Path] = None,
    ) -> None:
        self.events_file = Path(events_file) if events_file else None
        if cw_home is not None:
            self.cw_home: Optional[Path] = Path(cw_home)
        elif "CW_HOME" in os.environ:
            self.cw_home = Path(os.environ["CW_HOME"])
        else:
            default_cw = os.path.expanduser("~/.context-wall")
            self.cw_home = Path(default_cw) if os.path.isdir(default_cw) else None

        self.cw_room = cw_room

        if cw_events_file:
            self.cw_events_file: Optional[Path] = Path(cw_events_file)
        elif self.cw_home:
            self.cw_events_file = self.cw_home / "rooms" / self.cw_room / "events.jsonl"
        else:
            self.cw_events_file = None

        if state is not None:
            self.state = state
        elif state_file and Path(state_file).is_file():
            self.state = ProjectionState.load(state_file)
        else:
            self.state = None

    def audit(self) -> ReconciliationReport:
        anomalies: List[Dict[str, Any]] = []

        total_broker_events = 0
        agents_enqueued: Set[str] = set()
        enqueued_event_ids: Set[str] = set()
        refusals_count = 0
        uncertain_events: Dict[str, Dict[str, Any]] = {}

        # 1. Audit authoritative broker events
        if self.events_file and self.events_file.is_file():
            with open(self.events_file, "r", encoding="utf-8") as f:
                for line_idx, line in enumerate(f, start=1):
                    line_str = line.strip()
                    if not line_str:
                        continue
                    try:
                        record = json.loads(line_str)
                    except json.JSONDecodeError:
                        anomalies.append({
                            "code": "MALFORMED_JSON_LINE",
                            "line": line_idx,
                            "details": f"Failed parsing JSON on line {line_idx}",
                        })
                        continue

                    total_broker_events += 1
                    rec = record.get("rec")

                    if rec == "enqueue":
                        ag = record.get("agent_id")
                        ev_id = record.get("event_id")
                        if ag in TRACKED_AGENTS:
                            agents_enqueued.add(ag)
                        if ev_id:
                            enqueued_event_ids.add(ev_id)

                    elif rec == "close":
                        verdict = record.get("verdict", "")
                        ev_id = record.get("event_id")
                        ag = record.get("agent_id", "")
                        turn = record.get("turn", 0)

                        # m4: Skip noisy PASS records only
                        if verdict == "PASS" or ev_id == "PASS":
                            continue

                        # Check refusal and --ref requirement
                        if verdict in REFUSAL_VERDICTS or (verdict and verdict not in ADMITTED_VERDICTS):
                            refusals_count += 1
                            ref_str = str(ev_id) if (ev_id and str(ev_id).strip()) else f"refusal-turn-{turn}-{ag}"
                            if not ref_str.strip():
                                anomalies.append({
                                    "code": "MISSING_REF_ON_REFUSAL",
                                    "line": line_idx,
                                    "event_id": ev_id,
                                    "verdict": verdict,
                                    "details": f"Refusal verdict {verdict} missing non-empty --ref identifier",
                                })

                        if verdict in ("INPUT_UNCERTAIN", "OUTCOME_UNCERTAIN"):
                            target_id = str(ev_id) if (ev_id and str(ev_id).strip()) else f"uncertain-turn-{turn}-{ag}"
                            uncertain_events[target_id] = {
                                "verdict": verdict,
                                "line": line_idx,
                                "ts_ms": record.get("ts_ms", 0),
                            }

                    elif rec == "control":
                        op = record.get("op", "")
                        if op == "park":
                            refusals_count += 1
                            target = extract_park_target(record)
                            if not str(target).strip():
                                anomalies.append({
                                    "code": "MISSING_REF_ON_REFUSAL",
                                    "line": line_idx,
                                    "details": "Control park record lacks target reference",
                                })
                        elif op == "reconcile":
                            # m6: Explicit reconcile clears prior uncertain events (resume does not)
                            uncertain_events.clear()

        # m6: Check unreconciled uncertain events
        if uncertain_events:
            for ev_id, info in sorted(uncertain_events.items()):
                anomalies.append({
                    "code": "UNRECONCILED_UNCERTAIN_EVENT",
                    "event_id": ev_id,
                    "verdict": info["verdict"],
                    "line": info["line"],
                    "details": f"Event {ev_id} ended with {info['verdict']} on line {info['line']} but queue was never reconciled",
                })

        # 2. Audit TaskLight room events
        cw_planned_agents: Set[str] = set()
        cw_step_agents: Set[str] = set()
        cw_closed_agents: Set[str] = set()

        cw_home_available = (self.cw_home is not None or self.cw_events_file is not None)

        if self.cw_events_file and self.cw_events_file.is_file():
            with open(self.cw_events_file, "r", encoding="utf-8") as f:
                for line in f:
                    line_str = line.strip()
                    if not line_str:
                        continue
                    try:
                        obj = json.loads(line_str)
                    except json.JSONDecodeError:
                        continue

                    act = obj.get("act")
                    agent = obj.get("agent")
                    if agent in TRACKED_AGENTS:
                        if act == "plan":
                            cw_planned_agents.add(agent)
                        elif act == "step":
                            cw_step_agents.add(agent)
                        elif act == "close":
                            cw_closed_agents.add(agent)

        # M1: Cross-check with projection state
        if self.state:
            for ag in self.state.planned_agents:
                if ag in TRACKED_AGENTS:
                    cw_planned_agents.add(ag)

            if cw_home_available:
                # TaskLight room store is the sole ground truth.
                # Do NOT union state.closed_agents into cw_closed_agents.
                # If state claims closed while room store lacks close, flag STATE_ROOM_MISMATCH.
                for ag in self.state.closed_agents:
                    if ag in TRACKED_AGENTS and ag not in cw_closed_agents:
                        anomalies.append({
                            "code": "STATE_ROOM_MISMATCH",
                            "agent_id": ag,
                            "details": (
                                f"Projection state claims agent {ag} closed, "
                                f"but TaskLight room store ({self.cw_room}) lacks matching close event"
                            ),
                        })
            else:
                for ag in self.state.closed_agents:
                    if ag in TRACKED_AGENTS:
                        cw_closed_agents.add(ag)

        # Determine all agents that initiated tasks
        active_agents = (agents_enqueued | cw_planned_agents | cw_step_agents) & set(TRACKED_AGENTS)

        # Negative-control check: Every agent that planned/enqueued MUST have close_task in room store
        for agent in sorted(active_agents):
            if agent not in cw_closed_agents:
                anomalies.append({
                    "code": "MISSING_CLOSE_TASK",
                    "agent_id": agent,
                    "details": f"Agent {agent} emitted post_plan/enqueue/step but lacks a matching close_task in room store",
                })

        clean = (len(anomalies) == 0)
        status = "CLEAN" if clean else "ANOMALIES_DETECTED"

        stats = {
            "total_broker_events": total_broker_events,
            "agents_enqueued": sorted(agents_enqueued),
            "agents_planned": sorted(cw_planned_agents),
            "agents_closed": sorted(cw_closed_agents),
            "refusals_count": refusals_count,
            "uncertain_events_count": len(uncertain_events),
        }

        return ReconciliationReport(
            clean=clean,
            status=status,
            anomalies=anomalies,
            stats=stats,
        )


def audit_events(
    events_file: str | Path = DEFAULT_EVENTS_LOG,
    cw_home: Optional[str | Path] = None,
    cw_room: str = DEFAULT_CW_ROOM,
    state_file: Optional[str | Path] = None,
) -> ReconciliationReport:
    """Convenience helper to run audit."""
    reconciler = Reconciler(
        events_file=events_file,
        cw_home=cw_home,
        cw_room=cw_room,
        state_file=state_file,
    )
    return reconciler.audit()


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="OpenSwitchboard & TaskLight Projection Reconciler (swarm.projection.reconciler)",
    )
    parser.add_argument(
        "--events",
        "--events-file",
        dest="events_file",
        default=os.environ.get("SWARM_EVENTS_LOG", DEFAULT_EVENTS_LOG),
        help="Path to authoritative events.jsonl",
    )
    parser.add_argument(
        "--cw-home",
        default=None,
        help="Context-wall home directory (defaults to CW_HOME or ~/.context-wall)",
    )
    parser.add_argument(
        "--cw-room",
        default=DEFAULT_CW_ROOM,
        help="Target TaskLight context-wall room slug",
    )
    parser.add_argument(
        "--state-file",
        default=None,
        help="Path to cursor state JSON file",
    )
    return parser.parse_args(argv)


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = parse_args(argv)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(name)s: %(message)s")

    report = audit_events(
        events_file=args.events_file,
        cw_home=args.cw_home,
        cw_room=args.cw_room,
        state_file=args.state_file,
    )

    print(report.to_json(indent=2))
    return 0 if report.clean else 1


if __name__ == "__main__":
    sys.exit(main())

