def fake_vision(root, plan):
    """plan: dict key -> rc or 'timeout'; 'hover' for --xy; 'look' -> 'fail' or ok."""
    src = root / "src.png"
    from PIL import Image
    Image.new("RGB", (1920, 1080), (1, 2, 3)).save(src)
    calls = []

    def runner(cmd, timeout_s):
        args = cmd[3:]
        calls.append(args)
        if args[0] == "look":
            if plan.get("look_fail_after") is not None and sum(1 for c in calls if c[0] == "look") > plan["look_fail_after"]:
                return subprocess.CompletedProcess(cmd, 1, "", "boom")
            return subprocess.CompletedProcess(cmd, 0, json.dumps({"frame": str(src)}), "")
        if "--xy" in args:
            r = plan.get("hover", 0)
        else:
            r = plan.get(args[args.index("--key") + 1], 0)
        if r == "timeout":
            raise subprocess.TimeoutExpired(cmd, timeout_s)
        out = json.dumps({"changed_regions": [[100, 100, 50, 50]]}) if r == 0 else "{}"
        return subprocess.CompletedProcess(cmd, r, out, "")
    return runner, calls


def gui_case(root, plan, keys, vision_mode="mock"):
    runner, calls = fake_vision(root, plan)
    b = B.SwarmBroker(mkcfg(root, vision_mode=vision_mode), vision_runner=runner)
    put(root, "camera-agent", "g.json", base_intent("camera-agent", "g1", lane="gui", keys=keys,
                                                     footprint=[0, 80, 1580, 900], based_on_frame=b.head_frame))
    b.step_sweep()
    b.close()
    c = closes(root)
    return {"verdict": [(x["verdict"], x["reason"]) for x in c], "view_epoch": b.view_epoch,
            "queue_state": b.queue_state, "tick": b.tick, "head": b.head_frame,
            "acts": [a for a in calls if a[0] == "act"].__len__()}


