@probe("EV_append_only")
def _(root):
    ev = root / "events.jsonl"
    ev.write_text('{"v":1,"rec":"sentinel"}\n')
    prefix = ev.read_bytes()
    sizes = []
    orig = B.SwarmBroker._emit_event

    def spy(self, rec):
        orig(self, rec)
        sizes.append(ev.stat().st_size)
    B.SwarmBroker._emit_event = spy
    try:
        b = B.SwarmBroker(mkcfg(root, script_timeout_s=2.0), outbox_poll_hook=bridge_hook(root))
        for i in range(3):
            put(root, "modeler-agent", f"a{i}.json", base_intent("modeler-agent", f"a{i}", created_ts_ms=i))
        for _ in range(4):
            b.step_sweep()
        b.close()
        b2 = B.SwarmBroker(mkcfg(root, script_timeout_s=2.0))  # restart same log
        b2.close()
    finally:
        B.SwarmBroker._emit_event = orig
    data = ev.read_bytes()
    return {"prefix_kept": data.startswith(prefix), "monotonic": all(x < y for x, y in zip(sizes, sizes[1:])),
            "n_emits": len(sizes), "all_lines_json": all(json.loads(l) for l in data.splitlines())}


